from pathlib import Path
import base64
def put(path,data):
    p=Path(path); p.parent.mkdir(parents=True,exist_ok=True); p.write_text(data,encoding="utf-8")
def putb(path,data):
    p=Path(path); p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(base64.b64decode(data))
ICONS={'mdpi': '', 'hdpi': '', 'xhdpi': '', 'xxhdpi': '', 'xxxhdpi': ''}
for density,data in ICONS.items():
    putb("app/src/main/res/mipmap-"+density+"/ic_launcher.png",data)
    putb("app/src/main/res/mipmap-"+density+"/ic_launcher_round.png",data)
putb("app/src/main/res/drawable/situsnap_splash_mark.png",'')
